# Update the stored solver to use the color immediately below the marker, as shown by demo 1.
source='''def transform(grid):
    """Fill gaps between horizontally or vertically aligned marker cells."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    marker = max(colors - {min(colors)}) if len(colors) > 1 else None
    if marker is None:
        return out
    fill = marker - 1
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = fill
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = fill
    return out
'''
